def compute(vars):
    total_change = vars["v1"] + vars["v2"] + vars["v3"]
    reduction = -total_change
    return {
        "value": reduction,
        "trace": {
            "total_signed_change": total_change,
            "output_meta": {
                "currency": None,
                "scale": "million",
                "unit": "shares"
            }
        }
    }
